export const SEALS=[{name:'Selo da Floresta',floor:4,cost:110},{name:'Selo Ancestral',floor:8,cost:260},{name:'Selo do Manto',floor:12,cost:480}];
export const distance=(a,b)=>Math.abs(a.x-b.x)+Math.abs(a.y-b.y);
export const biomeIndex=f=>Math.min(3,Math.floor((f-1)/4));
export const has=(s,id)=>s.equipped.includes(id);
export function rng(seed){let n=seed>>>0;return()=>{n+=0x6D2B79F5;let t=n;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296;};}
export function createState(seed=Math.floor(Math.random()*2147483647)){return{version:2,seed,bank:30,essence:0,level:1,core:0,seals:0,best:0,attempts:0,deaths:0,unlocked:[],equipped:[],totalGems:0,bestCombo:0,run:null,lastResult:null};}
export const maxRhythm=s=>100+s.core*10;
export const windowMs=s=>100+(has(s,'ear')?25:0);
export const power=s=>s.level+(has(s,'force')?1:0);
export const depthLimit=s=>4+s.seals*4;
export const upgradeCost=s=>Math.round(35*Math.pow(1.55,s.level-1));
export const coreCost=s=>Math.round(45*Math.pow(1.6,s.core));
function event(r,type,data={}){r.events.push({type,...data});}
export function walkable(room,x,y){return x>=1&&y>=1&&x<COLS-1&&y<ROWS-1&&!room.rocks.some(p=>p.x===x&&p.y===y);}
export function pathTo(room,from,to){const queue=[{x:from.x,y:from.y,path:[]}],seen=new Set([`${from.x},${from.y}`]);for(let i=0;i<queue.length;i++){const p=queue[i];if(p.x===to.x&&p.y===to.y)return p.path;for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const x=p.x+dx,y=p.y+dy,key=`${x},${y}`;if(!seen.has(key)&&walkable(room,x,y)){seen.add(key);queue.push({x,y,path:[...p.path,{x,y}]});}}}return [];}
function randomFree(r,random,minDistance=0){for(let i=0;i<200;i++){const p={x:2+Math.floor(random()*17),y:2+Math.floor(random()*11)};if(walkable(r.room,p.x,p.y)&&distance(p,r.player)>=minDistance&&!r.room.nodes.some(n=>n.hp>0&&distance(n,p)<2)&&!r.room.enemies.some(e=>e.hp>0&&distance(e,p)<2)&&distance(p,{x:18,y:2})>2&&pathTo(r.room,r.player,p).length)return p;}return null;}
function spawnCrystal(s,random,kind){const r=s.run,p=randomFree(r,random,2);if(!p)return;const k=kind??Math.floor(random()*4),def=CRYSTALS[k],hp=def.hp+Math.floor((r.floor-1)*.65);const n={id:r.room.nextId++,type:'crystal',kind:k,...p,hp,maxHp:hp,value:Math.round(def.value*(1+biomeIndex(r.floor)*.35)),born:r.beat};r.room.nodes.push(n);event(r,'sprout',{...p,color:def.color});return n;}
function spawnEnemy(s,random){const r=s.run,p=randomFree(r,random,7);if(!p)return;const kind=r.floor<3?0:Math.floor(random()*Math.min(3,1+Math.ceil(r.floor/4))),hp=2+Math.floor(r.floor*.6)+(kind===2?3:0);r.room.enemies.push({id:r.room.nextId++,type:'enemy',kind,...p,hp,maxHp:hp,windup:null,stunUntil:-1});event(r,'spawn',{...p});}
export function generateRoom(s){const r=s.run,random=rng(s.seed+s.attempts*977+r.floor*113);r.room={rocks:[],nodes:[],enemies:[],nextId:0,quota:8+r.floor,charge:0,goal:Math.min(12,3+Math.floor((r.floor-1)*.7)),cleared:false,gardener:{x:10,y:7},seed:Math.floor(random()*1e9)};r.player={x:3,y:11};for(let i=0;i<30;i++){const p={x:2+Math.floor(random()*17),y:3+Math.floor(random()*9)};if(distance(p,r.player)<3||distance(p,{x:18,y:2})<3||r.room.rocks.some(q=>distance(p,q)<2))continue;r.room.rocks.push(p);if(!pathTo(r.room,r.player,{x:18,y:2}).length)r.room.rocks.pop();}for(let i=0;i<7;i++)spawnCrystal(s,random,i%4);spawnEnemy(s,random);if(r.floor>4)spawnEnemy(s,random);r.events=[];return r.room;}
export function startRun(s){if(s.run)return false;s.attempts++;s.lastResult=null;s.run={floor:1,bag:0,rhythm:maxRhythm(s),combo:0,peak:0,beat:-1,acted:-1,missed:-1,guardUntil:-1,revived:false,events:[],player:{x:3,y:11},room:null};s.best=Math.max(s.best,1);generateRoom(s);return true;}
function lose(s,amount,reason){const r=s.run;if(!r)return;const loss=amount*(has(s,'flow')&&reason!=='attack'?.65:1);r.rhythm=Math.max(0,r.rhythm-loss);r.combo=0;event(r,'hurt',{amount:Math.round(loss),reason});if(r.rhythm<=0){if(has(s,'revive')&&!r.revived){r.revived=true;r.rhythm=30;event(r,'revive');}else finishRun(s,'death');}}
export function finishRun(s,reason='return'){const r=s.run;if(!r)return false;const kept=Math.floor(r.bag*(['death','retreat'].includes(reason)?.5:1));s.bank+=kept;s.totalGems+=kept;if(reason==='death')s.deaths++;s.lastResult={reason,floor:r.floor,bag:r.bag,kept,lost:r.bag-kept,peak:r.peak};s.run=null;return true;}
function checkClear(s){const r=s.run;if(!r||r.room.cleared)return;if(r.room.charge>=r.room.quota&&r.combo>=r.room.goal){r.room.cleared=true;r.room.enemies=[];s.essence++;event(r,'clear');}}
function damageTarget(s,target,damage){const r=s.run;if(!r||target.hp<=0)return;target.hp=Math.max(0,target.hp-damage);event(r,'hit',{x:target.x,y:target.y,damage,color:target.type==='enemy'?'#fea7a7':CRYSTALS[target.kind].color});if(target.hp>0)return;if(target.type==='crystal'){const def=CRYSTALS[target.kind],value=Math.round(target.value*(has(s,'fortune')?1.3:1)*(1+Math.min(20,r.combo)*.025));r.bag+=value;r.room.charge+=has(s,'symbiosis')&&target.kind===3?3:def.charge;r.rhythm=Math.min(maxRhythm(s),r.rhythm+(target.kind===3?12+(has(s,'symbiosis')?10:0):0)+(has(s,'harvest')?4:0));event(r,'loot',{x:target.x,y:target.y,value,color:def.color});}else{r.bag+=4+biomeIndex(r.floor)*3;r.rhythm=Math.min(maxRhythm(s),r.rhythm+4);if(has(s,'hunter'))r.room.charge+=2;event(r,'kill',{x:target.x,y:target.y});}}
export function act(s,action,phase){const r=s.run;if(!r||r.room.cleared)return{ok:false};const beat=Math.round(phase);if(beat===r.acted||beat===r.missed)return{ok:false,duplicate:true};if(Math.abs(phase-beat)*BEAT*1000>windowMs(s)){r.missed=beat;lose(s,8+r.floor*.4,'timing');return{ok:false,miss:true};}r.acted=beat;r.combo++;r.peak=Math.max(r.peak,r.combo);s.bestCombo=Math.max(s.bestCombo,r.combo);r.rhythm=Math.min(maxRhythm(s),r.rhythm+1.1);if(has(s,'breath')&&r.combo%4===0)r.rhythm=Math.min(maxRhythm(s),r.rhythm+6);const target=action.id!=null?[...r.room.nodes,...r.room.enemies].find(x=>x.id===action.id&&x.hp>0):null;const from={...r.player};let destination;
 if(action.type==='dodge'){destination={...r.player};for(let i=0;i<(has(s,'dash')?3:2);i++){const x=destination.x+action.dx,y=destination.y+action.dy;if(walkable(r.room,x,y))destination={x,y};}r.guardUntil=beat+(has(s,'guard')?2:0);}else if(action.type==='move')destination={x:action.x,y:action.y};else if(target){const options=[[1,0],[-1,0],[0,1],[0,-1]].map(([dx,dy])=>({x:target.x+dx,y:target.y+dy})).filter(p=>walkable(r.room,p.x,p.y));const paths=options.map(p=>({p,path:pathTo(r.room,r.player,p)})).filter(p=>p.path.length||distance(p.p,r.player)===0).sort((a,b)=>a.path.length-b.path.length);destination=paths[0]?.p;}
 if(destination&&walkable(r.room,destination.x,destination.y)){const path=pathTo(r.room,r.player,destination),limit=action.type==='dodge'?3:has(s,'dash')?7:5;r.player=path[Math.min(path.length,limit)-1]||r.player;}event(r,'dash',{from,to:{...r.player}});event(r,'perfect',{combo:r.combo});if(target&&distance(r.player,target)<=1){let dmg=power(s)+(r.combo>=8&&has(s,'fury')?3:0);if(target.type==='crystal'&&target.kind===2&&has(s,'shatter'))dmg*=2;damageTarget(s,target,dmg);if(target.type==='enemy'&&has(s,'stun'))target.stunUntil=beat+2;}if(r.combo%4===0&&has(s,'chain')){for(const t of [...r.room.nodes,...r.room.enemies])if(t.hp>0&&t!==target&&distance(t,r.player)<=3)damageTarget(s,t,power(s));event(r,'wave',{...r.player});}if(r.combo%4===0&&has(s,'echo')){const n=r.room.nodes.filter(n=>n.hp>0).sort((a,b)=>distance(a,r.player)-distance(b,r.player))[0];if(n)damageTarget(s,n,2);}checkClear(s);return{ok:true};}
export function tick(s,beat){const r=s.run;if(!r||r.room.cleared||beat<=r.beat)return;r.beat=beat;if(beat>=4&&r.acted!==beat&&r.missed!==beat){lose(s,3+r.floor*.3,'silence');if(!s.run)return;}const random=rng(r.room.seed+beat*7919);if(beat>=4){for(const e of r.room.enemies){if(e.hp<=0||beat<=e.stunUntil)continue;if(e.windup){if(beat>=e.windup.beat){if(distance(r.player,e.windup)<=e.windup.radius&&r.guardUntil<beat){lose(s,12+r.floor*1.1,'attack');if(!s.run)return;}e.windup=null;}continue;}if(distance(e,r.player)<=2){e.windup={...r.player,beat:beat+(e.kind===2?2:1),radius:e.kind===2?1:0};event(r,'danger',{x:e.windup.x,y:e.windup.y});}else if(beat%(e.kind===0?3:2)===0){const path=pathTo(r.room,e,r.player),p=path[Math.min(path.length,e.kind===1?2:1)-1];if(p){e.x=p.x;e.y=p.y;}}}if(beat%Math.max(7,14-Math.floor(r.floor/2))===0&&r.room.enemies.filter(e=>e.hp>0).length<Math.min(5,2+Math.floor(r.floor/4)))spawnEnemy(s,random);}if(beat>0&&beat%(has(s,'seed')?4:6)===0&&r.room.nodes.filter(n=>n.hp>0).length<10){const n=spawnCrystal(s,random);if(n)r.room.gardener={x:n.x,y:Math.min(ROWS-2,n.y+1)};}r.room.nodes=r.room.nodes.filter(n=>n.hp>0||beat-n.born<12);r.room.enemies=r.room.enemies.filter(e=>e.hp>0);checkClear(s);}
export function descend(s){const r=s.run;if(!r||!r.room.cleared||r.floor>=depthLimit(s)||r.floor>=16)return false;r.floor++;s.best=Math.max(s.best,r.floor);r.rhythm=Math.min(maxRhythm(s),r.rhythm+15);r.combo=0;r.beat=-1;r.acted=-1;r.missed=-1;r.guardUntil=-1;generateRoom(s);return true;}
export function purchaseUpgrade(s){const cost=upgradeCost(s);if(s.run||s.bank<cost||s.level>=12)return false;s.bank-=cost;s.level++;return true;}
export function purchaseCore(s){const cost=coreCost(s);if(s.run||s.bank<cost||s.core>=6)return false;s.bank-=cost;s.core++;return true;}
export function purchaseSeal(s){const seal=SEALS[s.seals];if(s.run||!seal||s.best<seal.floor||s.bank<seal.cost)return false;s.bank-=seal.cost;s.seals++;return true;}
export function canLearn(s,k){return !s.run&&!s.unlocked.includes(k.id)&&s.bank>=k.cost&&s.essence>=k.ess&&k.parents.every(p=>p==='root'||s.unlocked.includes(p));}
export function learn(s,id){const k=SKILLS.find(k=>k.id===id);if(!k||!canLearn(s,k))return false;s.bank-=k.cost;s.essence-=k.ess;s.unlocked.push(id);if(s.equipped.length<5)s.equipped.push(id);return true;}
export function equip(s,id){if(s.run||!s.unlocked.includes(id))return false;if(s.equipped.includes(id))s.equipped=s.equipped.filter(x=>x!==id);else if(s.equipped.length<5)s.equipped.push(id);else return false;return true;}
export function restoreState(raw){try{const a=JSON.parse(raw);if(!a||![1,2].includes(a.version))return null;if(a.version===1){if(!Number.isFinite(a.gems)||a.gems<0)return null;const s=createState(Number.isInteger(a.seed)?a.seed:1);s.bank=Math.floor(a.gems);s.essence=Math.max(0,Math.floor(a.essence||0));s.level=Math.min(12,Math.max(1,Math.floor(a.level||1)));s.best=Math.min(16,Math.max(0,Math.floor(a.best||0)));const map={rhythm:'ear',resonance:'breath',fortune:'fortune',chain:'chain',force:'force',echo:'echo'};s.unlocked=[...new Set((a.skills||[]).map(id=>map[id]).filter(Boolean))];s.equipped=s.unlocked.slice(0,5);return s;}const s={...createState(),...a};for(const k of ['bank','essence','level','core','seals','best','attempts','deaths','bestCombo','totalGems'])if(!Number.isFinite(s[k])||s[k]<0||!Number.isInteger(s[k]))return null;if(s.level<1||s.level>12||s.core>6||s.seals>3||s.best>16)return null;if(!Array.isArray(s.unlocked)||!Array.isArray(s.equipped)||s.equipped.length>5)return null;s.unlocked=[...new Set(s.unlocked.filter(id=>SKILLS.some(k=>k.id===id)))];s.equipped=[...new Set(s.equipped.filter(id=>s.unlocked.includes(id)))];if(s.run){const r=s.run;if(!Number.isInteger(r.floor)||r.floor<1||r.floor>depthLimit(s)||!Number.isFinite(r.rhythm)||r.rhythm<=0||r.rhythm>maxRhythm(s)||!Number.isInteger(r.bag)||r.bag<0||!r.room||!r.player)return null;for(const arr of ['nodes','enemies','rocks'])if(!Array.isArray(r.room[arr])||r.room[arr].length>200)return null;for(const p of [r.player,...r.room.nodes,...r.room.enemies,...r.room.rocks])if(!Number.isInteger(p.x)||!Number.isInteger(p.y)||p.x<0||p.y<0||p.x>=COLS||p.y>=ROWS)return null;for(const n of [...r.room.nodes,...r.room.enemies])if(!Number.isFinite(n.hp)||!Number.isFinite(n.maxHp)||n.hp<0||n.hp>n.maxHp||![0,1,2,3].includes(n.kind))return null;r.events=[];}return s;}catch{return null;}}
